package nl.jaarzon;

/** Kadaster/PDOK BRK landgebied LND6030, CC BY 4.0.
 * Complete European Netherlands border including enclave holes, rounded to 1e-6 degrees.
 * Offline compressed coordinates; provenance: docs/netherlands-boundary.md.
 * No network, database, or third-party runtime dependency.
 */
public final class NetherlandsBoundary {
    private NetherlandsBoundary() { }
    private static final String[] DATA = {
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    };
    private static final double[][][] POLYGONS = decode();
    private static double[][][] decode() {
        byte[] bytes = java.util.Base64.getDecoder().decode(String.join("", DATA));
        try (java.io.DataInputStream in = new java.io.DataInputStream(new java.util.zip.GZIPInputStream(new java.io.ByteArrayInputStream(bytes)))) {
            double[][][] polygons = new double[in.readInt()][][];
            for (int p = 0; p < polygons.length; p++) {
                polygons[p] = new double[in.readInt()][];
                for (int r = 0; r < polygons[p].length; r++) {
                    double[] ring = new double[in.readInt()*2];
                    for (int i = 0; i < ring.length; i++) ring[i] = in.readInt()/1_000_000.0;
                    polygons[p][r] = ring;
                }
            }
            return polygons;
        } catch (java.io.IOException error) { throw new ExceptionInInitializerError(error); }
    }
    public static boolean contains(double latitude, double longitude) {
        if (!Double.isFinite(latitude) || !Double.isFinite(longitude)
                || latitude < 50 || latitude > 54.5 || longitude < 3 || longitude > 8) return false;
        for (double[][] polygon : POLYGONS) {
            if (!inside(polygon[0], latitude, longitude)) continue;
            boolean hole = false;
            for (int r = 1; r < polygon.length; r++) if (inside(polygon[r],latitude,longitude)) { hole = true; break; }
            if (!hole) return true;
        }
        return false;
    }
    private static boolean inside(double[] ring, double latitude, double longitude) {
        boolean inside = false;
        for (int i = 0, j = ring.length-2; i < ring.length; j = i, i += 2) {
            double x1 = ring[j], y1 = ring[j+1], x2 = ring[i], y2 = ring[i+1];
            double cross = (longitude-x1)*(y2-y1) - (latitude-y1)*(x2-x1);
            if (Math.abs(cross) < 1e-12 && longitude >= Math.min(x1,x2) && longitude <= Math.max(x1,x2)
                    && latitude >= Math.min(y1,y2) && latitude <= Math.max(y1,y2)) return true;
            if ((y1 > latitude) != (y2 > latitude)
                    && longitude < x1 + (latitude-y1)*(x2-x1)/(y2-y1)) inside = !inside;
        }
        return inside;
    }
}
